"""Summarize completed web benchmark runs and plot repeat ranges, never pooled claims."""
import argparse,csv,json,statistics as st,tarfile
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
parser=argparse.ArgumentParser();parser.add_argument('data',type=Path);parser.add_argument('output',type=Path);parser.add_argument('--control',type=Path)
a=parser.parse_args();a.output.mkdir(parents=True,exist_ok=True)
manifest=json.loads((a.data/'manifest.json').read_text())
assert len(manifest['runs'])==len(manifest['cases'])*len(manifest['modes'])*manifest['repeats'],'Incomplete collection'
modes=manifest['modes'];cases=[c['name'] for c in manifest['cases']]
names={'direct':'Direct','inline':'Snapshot inline','threaded':'Threaded / rAF dispatch','scheduled':'Threaded / completion dispatch'}
colors=['#607d8b','#e6a23c','#bc5575','#168578']

from analysis import mean, percentile, analyze

runs=[json.loads((a.data/(key+'.json')).read_text()) for key in manifest['runs']]
assert all(r['valid'] and r['result']['engine']['is_debug']==False for r in runs)
for r in runs:
 if r['mode'] in ['threaded','scheduled']:assert any('WEB_POC_SCHEDULE completion_dispatch='+str(int(r['mode']=='scheduled'))+' metrics=1' in line for line in r['log'])
rows=[analyze(r,a.data) for r in runs]
for case in cases:assert len({tuple(m['canvas']) for r in runs if r['case']['name']==case for m in r['memory']})==1
with (a.output/'runs.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
groups={(case,mode):[r for r in rows if r['case']==case and r['mode']==mode] for case in cases for mode in modes}
def metric(case,mode,key):return mean([r[key] for r in groups[case,mode]])
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
def chart(key,title,ylabel,file):
 fig,ax=plt.subplots(figsize=(12,5.4));x=np.arange(len(cases));width=.19
 for i,mode in enumerate(modes):
  vals=[[r[key] for r in groups[c,mode]] for c in cases];ys=[mean(v) for v in vals]
  ax.bar(x+(i-1.5)*width,ys,width,color=colors[i],label=names[mode],yerr=[[max(0,y-min(v)) for y,v in zip(ys,vals)],[max(0,max(v)-y) for y,v in zip(ys,vals)]],capsize=3)
 ax.set(xticks=x,xticklabels=cases,ylabel=ylabel,title=title);ax.set_ylim(bottom=0);ax.grid(axis='y',alpha=.18);ax.set_axisbelow(True);ax.legend(fontsize=9,ncol=2)
 fig.text(.5,.015,'Visible Chrome / Apple M1 Pro · mean of 3 runs; whiskers show min/max run values',ha='center',fontsize=9)
 fig.tight_layout(rect=[0,.045,1,1]);fig.savefig(a.output/file,dpi=160);plt.close(fig)
chart('ups','Simulation throughput','Updates / second','throughput.png')
chart('fps','Render submission throughput (not displayed FPS)','Submissions / second','submissions.png')
chart('submit_p99','Render submission interval p99','Milliseconds (lower is better)','p99.png')
chart('wasm','WASM capacity with diagnostics enabled','MiB (capacity, not live allocations)','memory.png')
chart('cpu','Dedicated browser CPU use','Percent of one CPU core (100% = one core)','cpu.png')
chart('cpu_per_update','Browser CPU time per simulation update','CPU milliseconds / update','cpu-per-update.png')
chart('age','Simulation start → render submission','Mean milliseconds (not physical input latency)','age.png')
fig,axes=plt.subplots(1,2,figsize=(12,5))
for ax,key,title in zip(axes,['idle','queue'],['Idle after worker completion','Waiting for previous snapshot consumption']):
 for i,mode in enumerate(['threaded','scheduled']):
  ax.bar(np.arange(len(cases))+(i-.5)*.35,[metric(c,mode,key) for c in cases],.35,color=colors[i+2],label=names[mode])
 ax.set(xticks=np.arange(len(cases)),xticklabels=cases,ylabel='Mean ms / update',title=title);ax.tick_params(axis='x',labelrotation=25);ax.grid(axis='y',alpha=.18);ax.set_axisbelow(True)
axes[0].legend(fontsize=8);fig.tight_layout();fig.savefig(a.output/'waits.png',dpi=160);plt.close(fig)
lines=['# Web component threading: scheduling experiment', '', 'Measured 2026-10-03. Same instrumented PoC Release engine in every mode; direct is its legacy rendering path, not a separate vanilla-engine build.', '', '## Results', '', '| Workload | Direct updates/s | Inline | Current threaded | Completion dispatch | Completion vs direct |', '| --- | ---: | ---: | ---: | ---: | ---: |']
if all(c in cases for c in ['balanced','bunny30k','bunny10k','render50k','fill']):
 def gain(c):return (metric(c,'scheduled','ups')/metric(c,'direct','ups')-1)*100
 assessment=['## Assessment','',
 'Component threading is worth continuing as an **opt-in option for suitable workloads on this tested desktop target**, but these measurements do not justify making it the default for web exports. The current animation-callback-only dispatcher leaves avoidable worker idle time. Completion dispatch removes much of that wait, but snapshot costs and additional frame age remain.', '',
 f"- The balanced workload gains **{gain('balanced'):.1f}%** over direct. At 30k bunnies the gain is **{gain('bunny30k'):.1f}%**. These are gains against the same PoC binary’s direct path, not against a separate vanilla build. The 30k gain is modest and the ranges of run means overlap; treat its magnitude as tentative rather than a precise speedup.",
 f"- Render-heavy 50k sprites change by **{gain('render50k'):+.1f}%**, and the fill-heavy case by **{gain('fill'):+.1f}%**. The scheduler improvement does not make every workload faster.",
 f"- At 30k, worker idle time after completion falls from **{metric('bunny30k','threaded','idle'):.2f} ms** to **{metric('bunny30k','scheduled','idle'):.2f} ms**. This directly measures a scheduler weakness; it is not an inference from average update rate alone.",
 f"- At 10k, mean simulation-start-to-submit age is **{metric('bunny10k','direct','age'):.2f} ms direct**, **{metric('bunny10k','threaded','age'):.2f} ms current threaded**, and **{metric('bunny10k','scheduled','age'):.2f} ms completion dispatch**, despite similar throughput. Running ahead introduces a latency tradeoff.",
 f"- Balanced-workload CPU time per update is approximately **{metric('balanced','direct','cpu_per_update'):.2f} ms direct** and **{metric('balanced','scheduled','cpu_per_update'):.2f} ms completion dispatch**. Mean throughput rises, but submission-interval p99 changes from **{metric('balanced','direct','submit_p99'):.2f} ms** to **{metric('balanced','scheduled','submit_p99'):.2f} ms**: this is not a demonstrated tail-latency improvement.",
 f"- In the fill case, mean render span is **{metric('fill','direct','render'):.2f} ms direct** versus **{metric('fill','scheduled','render'):.2f} ms completion dispatch**, with only **{metric('fill','scheduled','simulation'):.2f} ms** of simulation. There is insufficient simulation work to hide the longer render path. These elapsed spans include driver behavior; they do not isolate GPU time.", '',
 'Recommendation: retain direct mode and keep the experiment opt-in. Next quantify/remove the remaining synchronous window-state query and test a dispatch policy that limits how far simulation runs ahead, then validate the promising balanced workload on a lower-powered web device, and add only the component snapshot coverage needed for one representative gameplay replay. Measure physical input latency and power before treating the throughput gain as a product-level win. The broad 2D compatibility path remains serialized and cannot substitute for that replay evaluation.', '',
 'This result does not reproduce or invalidate the earlier screenshot comparison of an unidentified baseline at 30 updates/s versus threaded at 40. Engine identity, render harness and actual drawing-buffer dimensions differ; those exact screenshot conditions remain unverified.', '']
 lines[4:4]=assessment
for c in cases:
 vals=[metric(c,m,'ups') for m in modes];lines.append('| '+c+' | '+' | '.join(f'{v:.2f}' for v in vals)+f' | {(vals[3]/vals[0]-1)*100:+.1f}% |')
for title,file in [('Simulation throughput','throughput.png'),('Render submissions','submissions.png'),('Tail frame intervals','p99.png'),('Scheduling and queue waits','waits.png'),('CPU usage','cpu.png'),('CPU cost per update','cpu-per-update.png'),('Memory with instrumentation','memory.png'),('Frame age','age.png')]:lines+=['',f'### {title}','',f'![{title}]({file})']
lines+=['','## CPU stages and scheduler evidence','','Times below are per-frame elapsed CPU spans, not exclusive CPU time. Simulation and rendering overlap in threaded modes, so these columns must not be added together to predict throughput. Preparation includes command capture and housekeeping as well as sprite extraction. Queue wait is measured separately.','','| Workload | Mode | Simulation ms | Preparation ms | Render ms | Queue wait ms | Dispatch idle ms | Worker total ms | Callback interval ms |','| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
for c in cases:
 for m in modes:lines.append('| '+c+' | '+names[m]+' | '+' | '.join(f'{metric(c,m,k):.3f}' for k in ['simulation','preparation','render','queue','idle','worker','raf'])+' |')
lines+=['','Zero worker/scheduler columns in direct/inline mean not applicable, not a measured zero-cost scheduler.','','## Deadline and memory details','','p99 is the interval at or below which 99% of observed intervals fall. The table averages each run’s p99; it does not pool samples. “Over budget” means submission intervals exceeding 16.67 or 8.33 ms by more than 0.5 ms; these are diagnostic thresholds, not measured display-present misses.','','| Workload | Mode | Update p99 ms | Submit p99 ms | Over 60 Hz budget % | Over 120 Hz budget % | WASM MiB | Browser RSS MiB |','| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for c in cases:
 for m in modes:lines.append('| '+c+' | '+names[m]+' | '+' | '.join(f'{metric(c,m,k):.2f}' for k in ['update_p99','submit_p99','over_60','over_120','wasm','rss'])+' |')
if a.control:
 cm=json.loads((a.control/'manifest.json').read_text());assert len(cm['runs'])==len(cm['cases'])*len(cm['modes'])*cm['repeats'];cr=[analyze(json.loads((a.control/(k+'.json')).read_text()),a.control) for k in cm['runs']]
 lines+=['','## Instrumentation-off check (30k bunnies)','','| Mode | Updates/s | Run range | Peak WASM capacity range, MiB | Browser RSS MiB |','| --- | ---: | --- | ---: | ---: |']
 for m in modes:
  g=[r for r in cr if r['mode']==m];v=[r['ups'] for r in g];lines.append(f'| {names[m]} | {mean(v):.2f} | {min(v):.2f}–{max(v):.2f} | {min(r["wasm"] for r in g):.2f}–{max(r["wasm"] for r in g):.2f} | {mean([r["rss"] for r in g]):.1f} |')
if a.control:
 fig,axes=plt.subplots(1,2,figsize=(11,4.5))
 for ax,key,title,unit in zip(axes,['ups','wasm'],['30k bunnies: diagnostics disabled','30k bunnies: normal WASM capacity'],['Updates / second','MiB']):
  vals=[[r[key] for r in cr if r['mode']==m] for m in modes];ys=[mean(v) for v in vals]
  ax.bar(range(4),ys,color=colors,yerr=[[max(0,y-min(v)) for y,v in zip(ys,vals)],[max(0,max(v)-y) for y,v in zip(ys,vals)]],capsize=4)
  ax.set(xticks=range(4),xticklabels=['Direct','Inline','Threaded','Completion'],title=title,ylabel=unit);ax.grid(axis='y',alpha=.18);ax.set_axisbelow(True)
 fig.tight_layout();fig.savefig(a.output/'control.png',dpi=160);plt.close(fig)
 lines+=['','![Instrumentation-off throughput and memory](control.png)','','Bars show mean run values and whiskers their range; memory uses the maximum sampled capacity within each run. Completion-dispatch capacity varied between runs, as shown in the table. This is chunked capacity, not a precise live-allocation delta. These runs occurred after the instrumented matrix; differences between the two collections do not isolate instrumentation overhead from run-to-run variation.']
lines+=['','## Remaining owner-thread dependency', '', 'Follow-up measurement note: this report’s simulation-start-to-submit age excludes the window query described below. The cache/dispatch follow-up also measures dispatch-to-submit age to include that wait. This original collector used Playwright’s default focus emulation, so its focus/visibility samples did not independently establish real foreground state. The follow-up disables focus emulation and preserves failed focus checks as invalid attempts. These limits do not change the recorded numbers here.', '', 'Code review after collection found that StepFrame queries `WINDOW_STATE_OPENED` before the trace’s `input_begin` timestamp. Unlike `WINDOW_STATE_ICONIFIED`, that query is not served from the external window snapshot: `dmGraphics::GetWindowStateParam` synchronously dispatches it to browser main. If main is consuming a frame, this can delay the worker before simulation. Worker total includes that delay, while the simulation column begins later; the stage table is not a complete attribution of every wait. This call was not individually timed, so the amount attributable to it remains unverified. A focused follow-up should capture the open/closed state with the existing main-owned window/input snapshot and compare it behind an opt-in switch, preserving close-event ordering. No such change is included in the measured engine.', '', '## What changed','','- Direct: simulation and ordinary component rendering on browser main.','- Inline: sprite snapshots extracted and consumed on main; measures the refactoring and snapshot cost without parallelism.','- Current threaded: worker simulation/extraction, browser-main consumption; each animation callback starts another update only if the worker is idle.','- Completion dispatch: same snapshot and graphics ownership, but worker completion additionally queues a main-thread dispatch opportunity. Main samples input only while the worker is idle. Consumption remains on animation callbacks; the two-slot queue still applies backpressure. Rendering/update pause falls back to animation-callback dispatch. Default behavior is unchanged.','- Enable the experiment with `render.poc_web_schedule=1` alongside component threading. This is rejected for the serialized broad-2D path.','- Opt-in `render.poc_web_metrics=1` allows `render.sprite_trace=/trace.csv` on web and records bounded scheduler samples. Traces are exported only after shutdown/join. Buffers have fixed capacities; the runner rejects dropped samples.','','## Workloads','','- bunny10k / bunny20k / bunny30k: original Bunnymark sprite assets and engine-driven bouncing animations, fixed seed, initial population. Compiled into the shared native-benchmark harness; uses its sprite-compatible renderer and 60,000 sprite/object capacity settings (the original Bunnymark project used 32,765). The native harness also retains its graphics limits. Thus these absolute timings and memory capacities are not a reproduction of the original Bunnymark bundle; all four modes here share these settings.','- render50k: native benchmark with 50,000 small stationary sprites, one pass, no additional scripted simulation.','- simulation: 1,000 sprites plus 1,000,000 deterministic arithmetic iterations per update. This is a synthetic CPU stressor, not representative game logic.','- balanced: 10,000 sprites, 100,000 arithmetic iterations and scripted movement of every sprite per update.','- fill: 10,000 sprites scaled to 64 pixels, four render passes. This stresses fill/overdraw; GPU timing was not collected, so GPU saturation is not independently proved.','','The native workload code is copied by `scripts/web/benchmark/prepare.py`; the GUI component is removed because this test concerns overlapping sprite snapshots. Measurement/result output is adapted for the browser. Synthetic movement uses a fixed step per update; timed runs with different update counts therefore do not end at the same simulation state. This is controlled work per update, not a fixed-duration gameplay replay.','','## Method and limits','','- Visible Chrome, fresh browser for each run, DevTools closed, AC power checked before and after each run. Seven workloads × four modes × three repeats. Five-second warm-up and fifteen-second measurement; mode order rotates between repeats. No successful run was discarded.','- Browser '+runs[0]['browser']+'; hardware renderer '+runs[0]['gpu'][0]['deviceString']+'. Native display DPR is 2, but actual drawing buffers are verified separately: Bunnymark 720×720; synthetic scenes 1280×720. This differs from the earlier 1440×1440 Bunnymark run.','- Visibility/focus and fixed buffer size are sampled every two seconds. Occlusion is not independently detected. The automation uses a clean Chrome profile and its standard launch defaults, not the user’s existing profile.','- CPU stage timestamps and render submissions come from the engine trace, not the number of render-script callbacks. GPU completion and display presentation are not measured. Browser animation callbacks remain refresh-scheduled; this is not an uncapped native-style throughput test.','- Browser CPU percentage is summed process CPU-time delta over the memory-sampling interval. Processes absent from either endpoint are excluded. It is a utilization measure, not energy or power. Power and energy were not measured in this collection.','- Instrumented WASM capacity includes the existing 65,536-record CPU trace buffer in all modes and two 32,768-record scheduler buffers in threaded modes (about 1.5 MiB combined). Growth is chunked. Use the instrumentation-off comparison for production-like capacity at 30k. RSS includes browser/GPU processes, is noisy and can double-count shared pages.','- Simulation-start-to-submit age is a pipeline latency proxy, not physical input-to-display latency. Completion dispatch may reduce idle time while increasing queued frame age; throughput alone is not a release criterion.','- Chrome on one Apple M1 Pro is the only performance target measured. Firefox/Safari, lower-powered Android, real-project snapshot coverage, longer thermal runs, physical input latency and energy remain required before a broad web-target recommendation.','- The broad 2D compatibility mode is serialized and is deliberately excluded from claims about overlapping rendering. Mesh/models and unsupported extension components remain outside this evaluation.','','## Validation and reproduction','','All four modes matched the deterministic sprite fixture’s simulation checksum and screenshot hash. Both threaded schedulers passed context-loss shutdown; rendering pause/resume and input are exercised. Native test_engine rebuilt and the existing admission regression passed.','','Use the matching Emscripten 4.0.6 pthread CMake build and full Bob jar described in `engine/docs/WEB_COMPONENT_POC.md`. Prepare content with `scripts/web/benchmark/prepare.py NATIVE_PROJECT BUNNYMARK_PROJECT NEW_DIRECTORY`, build it with Bob, point `DEFOLD_WEB_POC_CONTENT` to its `build/default`, and copy `scripts/web/benchmark/index.html` into the web engine output directory. Serve with the provided COOP/COEP server at localhost:8766. Run `node scripts/web/benchmark/run.cjs NEW_RESULTS_DIRECTORY` with Playwright available through NODE_PATH. `METRICS=0` disables traces; optional final case name selects one workload. Run this report script with the raw directory and output directory, optionally `--control` for instrumentation-off results.','','Raw evidence is preserved in [raw-results.tar.gz](raw-results.tar.gz), containing the instrumented and control directories, plus locally at '+str(a.data.resolve())+'. Per-run JSON includes engine identity, mode banners, CPU/process/memory samples and scheduler samples; CSV files hold per-frame CPU traces. `runs.csv` contains report calculations. Failed setup pilots are retained separately and are not performance measurements.','']
(a.output/'REPORT.md').write_text('\n'.join(lines))
with tarfile.open(a.output/'raw-results.tar.gz','w:gz') as archive:
 archive.add(a.data,arcname=a.data.name)
 if a.control:archive.add(a.control,arcname=a.control.name)
print(a.output/'REPORT.md')
